   const basePattern=e.flowWidths?/[A-Za-z0-9]+(?:[.+-][A-Za-z0-9]+)*[+%]?|\s+|[^A-Za-z0-9\s]/gu:/[A-Za-z0-9]+|\s+|[^A-Za-z0-9\s]/gu;
