import {readTheme,validateTheme,STORAGE_KEY} from './theme.js';
import './theme.css';
let current=readTheme();
export const pageBrightnessUniform={value:current.pageBrightness};
let renderer;
let backdrop;
let pendingPreviewRevision;
export function themeFrameRendered(){
 if(pendingPreviewRevision===undefined)return;
 parent.postMessage({type:'htwkr-theme-applied',revision:pendingPreviewRevision},location.origin);
 pendingPreviewRevision=undefined;
}
function apply(value){
 current=validateTheme(value);
 pageBrightnessUniform.value=current.pageBrightness;
 for(const [key,value] of Object.entries(current.colors))document.documentElement.style.setProperty(`--theme-${key}`,value);
 document.documentElement.style.setProperty('--color-bg',current.colors.background);
 document.documentElement.style.setProperty('--color-text',current.colors.text);
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',current.colors.background);
 renderer?.setClearColor(current.colors.background);
 if(backdrop)backdrop.visible=current.colors.background==='#000000';
}
export function connectThemeRenderer(value,plane){renderer=value;backdrop=plane;apply(current);}
apply(current);
window.addEventListener('message',event=>{
 if(event.origin!==location.origin || event.source!==parent || event.data?.type!=='htwkr-theme-preview')return;
 try{apply(event.data.theme);pendingPreviewRevision=event.data.revision;}catch{/* Ignore invalid preview messages. */}
});
window.addEventListener('storage',event=>{if(parent===window && event.key===STORAGE_KEY)apply(readTheme());});
if(parent!==window){document.documentElement.classList.add('theme-preview');parent.postMessage({type:'htwkr-theme-ready'},location.origin);}
