import {gsap} from 'gsap';
import {motionDefaults,normalizeMotion,readMotion,MOTION_KEY} from './motion-config.js';
export function connectMotion(view){
 const defaults=motionDefaults(view);
 const apply=value=>{const config=normalizeMotion(value,defaults);config.pages.forEach((p,i)=>{const mat=view.pageMaterials[i];Object.assign(mat.userData,{turnParallaxScale:p.turn,pointerParallaxScale:p.pointer,ambientParallaxScale:p.ambient});for(const g of p.groups)for(const name of g.layers){const index=mat.userData.layerNames.indexOf(name);if(index>0)mat.moveFactors[index].set(g.x,g.y);}});window.__portfolioMotion.config=config;return config;};
 window.__portfolioMotion={defaults,config:null,apply};apply(readMotion(defaults));
 window.addEventListener('storage',event=>{if(event.key===MOTION_KEY)apply(readMotion(defaults));});
 window.addEventListener('message',event=>{
  if(event.origin!==location.origin||event.source!==parent||parent===window||event.data?.type!=='portfolio-motion')return;
  try{
   const {action,config,page,progress}=event.data;
   if(config)apply(config);
   const number=Math.max(1,Math.min(7,Number(page)||1));
   if(action==='show'&&view.ENTERED)view.setCurrentPage(number);
   if((action==='scrub'||action==='replay')&&view.ENTERED){view.setPageKill();view.currPageIndex=number;view.checkNavArrows();view.flipTimeline.progress((number+Math.max(0,Math.min(.95,Number(progress)||0)))/8);
    if(action==='replay')gsap.fromTo(view.flipTimeline,{progress:number/8},{progress:(number+.85)/8,duration:1.5,ease:'sine.inOut',repeat:1,yoyo:true,onComplete:()=>{view.flipTimeline.progress(number/8);gsap.set(view.draggableElement,{left:-number*view.dim.width});}});
    else gsap.set(view.draggableElement,{left:-(number+(Number(progress)||0))*view.dim.width});
   }
   parent.postMessage({type:'portfolio-motion-applied'},location.origin);
  }catch(error){parent.postMessage({type:'portfolio-motion-error',message:error.message},location.origin);}
 });
 if(parent!==window&&new URLSearchParams(location.search).has('motion-preview')){
  const announce=()=>{if(!view.ENTERED){requestAnimationFrame(announce);return;}parent.postMessage({type:'portfolio-motion-ready',defaults,config:window.__portfolioMotion.config},location.origin);};
  requestAnimationFrame(announce);
 }
}
